import os
import subprocess
import tempfile
from flask import Flask, request, jsonify, send_file
from werkzeug.utils import secure_filename
import yaml

app = Flask(__name__)
UPLOAD_DIR = '/tmp/reports'
TEMPLATE_DIR = '/opt/app/templates'

os.makedirs(UPLOAD_DIR, exist_ok=True)

def render_latex(template_name, user_data):
    """Render a LaTeX template with user-provided data and compile to PDF."""
    template_path = os.path.join(TEMPLATE_DIR, template_name)
    with open(template_path, 'r') as f:
        template_content = f.read()

    # Substitute placeholders in template
    for key, value in user_data.items():
        placeholder = '{{' + key + '}}'
        template_content = template_content.replace(placeholder, str(value))

    # Write rendered .tex file
    work_dir = tempfile.mkdtemp(dir=UPLOAD_DIR)
    tex_path = os.path.join(work_dir, 'output.tex')
    with open(tex_path, 'w') as f:
        f.write(template_content)

    # Compile LaTeX to PDF
    result = subprocess.run(
        ['pdflatex', '-interaction=nonstopmode', '-output-directory', work_dir, tex_path],
        capture_output=True, timeout=30, cwd=work_dir
    )

    pdf_path = os.path.join(work_dir, 'output.pdf')
    if os.path.exists(pdf_path):
        return pdf_path
    return None

@app.route('/api/reports/generate', methods=['POST'])
def generate_report():
    """Generate a PDF report from user-supplied data and a template."""
    if not request.is_json:
        return jsonify({'error': 'JSON required'}), 400

    payload = request.get_json()
    template_name = payload.get('template', 'quarterly_report.tex')
    user_data = payload.get('data', {})

    # Basic template name validation
    if '..' in template_name or template_name.startswith('/'):
        return jsonify({'error': 'Invalid template name'}), 400

    template_name = secure_filename(template_name)

    if not isinstance(user_data, dict):
        return jsonify({'error': 'data must be an object'}), 400

    # Limit number of fields
    if len(user_data) > 20:
        return jsonify({'error': 'Too many fields'}), 400

    try:
        pdf_path = render_latex(template_name, user_data)
    except subprocess.TimeoutExpired:
        return jsonify({'error': 'Rendering timeout'}), 504
    except Exception as e:
        return jsonify({'error': f'Rendering failed: {str(e)}'}), 500

    if pdf_path:
        return send_file(pdf_path, mimetype='application/pdf', as_attachment=True,
                         download_name='report.pdf')
    return jsonify({'error': 'PDF generation failed'}), 500

@app.route('/api/reports/templates', methods=['GET'])
def list_templates():
    """List available report templates."""
    templates = []
    for f in os.listdir(TEMPLATE_DIR):
        if f.endswith('.tex'):
            templates.append(f)
    return jsonify({'templates': templates})

@app.route('/api/config/reload', methods=['POST'])
def reload_config():
    """Reload application configuration from YAML file."""
    config_path = os.environ.get('APP_CONFIG', '/opt/app/config.yaml')
    try:
        with open(config_path, 'r') as f:
            config = yaml.safe_load(f)
        app.config.update(config or {})
        return jsonify({'status': 'reloaded'})
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
